#include <string>
#include <string_view>

std::string repeat(std::string_view text, int times = 2)
{
    std::string result{};
    for (int i{ 0 }; i < times; ++i)
    {
        result += text;
    }
    return result;
}

unitTests:
TEST("default is twice") { CHECK_EQ(repeat("ab"), "abab"); CHECK_EQ(repeat("-"), "--"); }
TEST("explicit count") { CHECK_EQ(repeat("ab", 3), "ababab"); CHECK_EQ(repeat("x", 5), "xxxxx"); }
TEST("zero times") { CHECK_EQ(repeat("abc", 0), ""); }

